"""Test helpers that build the compiled requirements files the tests read."""


def requirements_compiled_by_uv(source_name: str, output: str | None = "requirements.txt", options: str = "") -> str:
    """Return a file uv compiled from the source into the output, if any, with the options, pinning `flask==1.0`."""
    output_option = f" -o {output}" if output else ""
    options = f" {options}" if options else ""
    return (
        "# This file was autogenerated by uv via the following command:\n"
        f"#    uv pip compile {source_name}{output_option}{options}\n"
        "flask==1.0\n"
        f"    # via -r {source_name}\n"
    )


def requirements_compiled_by_pip_compile(
    source_name: str, output: str | None = "requirements.txt", options: str = ""
) -> str:
    """Return a file pip-compile compiled from the source into the output, with the options, pinning `flask==1.0`."""
    output_option = f" --output-file={output}" if output else ""
    options = f" {options}" if options else ""
    return (
        "#\n# This file is autogenerated by pip-compile with Python 3.12\n# by the following command:\n#\n"
        f"#    pip-compile{output_option}{options} {source_name}\n#\n"
        "flask==1.0\n"
        f"    # via -r {source_name}\n"
    )
